function main(): void {
  let line = "";
  for (const w of "a b  c".split(/\s+/)) {
    line = w;
  }
  console.log(line);
  const parts = "a1b".split(/\d/);
  const first: string = parts[0];
  console.log(first);
  const m = /^(?<name>[a-z]+)=(?<v>\d+)$/.exec("ab=12");
  if (m?.groups) {
    const o: Record<string, string> = {};
    o[m.groups.name] = m.groups.v;
    console.log(o);
  }
  const e = { "&": "&amp;", "<": "&lt;" } as Record<string, string>;
  console.log("a&<".replace(/[&<]/g, (c) => e[c]));
  const c = "&";
  const x: string = e[c] as string;
  console.log(x);
}
